-- The demo database behind every plan in this lesson (PGlite, PostgreSQL 18.3, TimeZone UTC).
CREATE TABLE customers (id int PRIMARY KEY, email text NOT NULL UNIQUE, region text);
CREATE TABLE orders (
  id          bigint PRIMARY KEY,
  customer_id int NOT NULL REFERENCES customers (id),
  placed_at   timestamptz NOT NULL,
  status      text NOT NULL,
  total       numeric(10,2) NOT NULL
);
INSERT INTO customers
SELECT g, 'c' || g || '@x.io', (ARRAY['eu', 'us', 'apac'])[1 + g % 3]
FROM generate_series(1, 2000) g;
INSERT INTO orders
SELECT g, 1 + (g * 7919) % 2000,
       timestamptz '2024-01-01 00:00+00' + g * interval '47 minutes',
       CASE WHEN g % 50 = 0 THEN 'refunded' ELSE 'paid' END,
       (g % 500) + 0.99
FROM generate_series(1, 20000) g;
CREATE INDEX orders_placed_at_idx   ON orders (placed_at);
CREATE INDEX orders_customer_id_idx ON orders (customer_id);
ANALYZE;

-- Then: read each plan bottom-up, compare rows= with actual rows=, look for the red flags.
EXPLAIN (ANALYZE, BUFFERS)
SELECT c.region, count(*) AS orders, sum(o.total) AS revenue
FROM orders o
JOIN customers c ON c.id = o.customer_id
WHERE o.placed_at >= '2024-02-01' AND o.placed_at < '2024-03-01'
GROUP BY c.region
ORDER BY revenue DESC;

