CREATE OR REPLACE FUNCTION plan_of(q text) RETURNS SETOF text LANGUAGE plpgsql AS $$
DECLARE r text; BEGIN FOR r IN EXECUTE 'EXPLAIN (COSTS OFF) ' || q LOOP RETURN NEXT r; END LOOP; END $$;
SET enable_seqscan = off;
WITH plan AS (
  SELECT line FROM plan_of('SELECT * FROM ticket_search') AS line
), shape AS (
  SELECT count(*) FILTER (WHERE line ~ '(Seq Scan|Index Scan|Index Only Scan) ') AS scans,
         count(*) FILTER (WHERE line ~ 'Index Cond:') AS conds
  FROM plan
)
SELECT s.id, s.subject, (sh.scans = sh.conds) AS index_driven
FROM ticket_search s
CROSS JOIN shape sh

